import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    try:
        import yaml
        data = yaml.load(json_str, Loader=yaml.Loader)
    except json.JSONDecodeError:
        return {}
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+[/\w\.-]*\??[/\w\.-=&%]*'
